mapper.select:
SELECT s.stock_code, s.stock_name, s.market, sp.base_date, sp.open_price, sp.close_price, sp.low_price, sp.high_price, sp.change_amount, ROUND(sp.change_amount / NULLIF(sp.close_price - sp.change_amount, 0) * 100, 2) AS change_rate, sp.volume FROM stock_price as sp JOIN stock_info as s on sp.stock_code = s.stock_code WHERE sp.stock_code = #{stockCode}
AND sp.base_date >= #{startDate}
AND sp.base_date <= #{endDate}
ORDER BY sp.base_date ASC
